function poly(points,fill='#f6f5e9',extra=''){return `<polygon points="${points}" fill="${fill}" ${extra}/>`}function line(d){return `<path d="${d}" fill="none"/>`}
function windowBox(x,y,w=17,h=27){return `<g>${poly(`${x},${y} ${x+w},${y-3} ${x+w},${y+h-3} ${x},${y+h}`,'#d8dfdc')}${line(`M${x+w/2} ${y-1.5}v${h}M${x} ${y+h/2}l${w}-3`)}</g>`}
